local temporary = require "spec.support.temporary"
require "titan-compiler.coder.core"
local h = require "spec.support.helpers"
local coder = require "titan-compiler.coder"
local coder_names = require "titan-compiler.coder.names"
local coder_declarations = require "titan-compiler.coder.declarations"
local types = require "titan-compiler.types"
local compiler_io = require "titan-compiler.io"
local platform = require "titan-compiler.platform"
local lfs = require "lfs"

local relocated

local GENERATED_HEADER_BANNER =
    "/* Generated by Titan: source foreign function interface. */"

local function with_header(contents, body)
    local path = temporary.name(".h")
    local file = assert(io.open(path, "wb"))
    assert(file:write(contents))
    assert(file:close())
    local results = table.pack(xpcall(function() return body(path) end,
        debug.traceback))
    os.remove(path)
    if not results[1] then error(results[2], 0) end
    return table.unpack(results, 2, results.n)
end

local function read_file(path)
    local file = assert(io.open(path, "rb"))
    local contents = assert(file:read("*a"))
    assert(file:close())
    return contents
end

local function cleanup()
    for _, path in ipairs({
        "test.c", "test.o", "test.so", "test.a", "test.titan.h", "test.ffi.h",
    }) do
        os.remove(path)
    end
    os.execute("rm -rf test.so.dSYM")
    for _, name in ipairs({ "foreign_export_provider", "foreign_export_consumer",
            "foreign_slot_provider", "foreign_slot_owner", "foreign_slot_consumer" }) do
        for _, suffix in ipairs({ ".titan", ".c", ".o", ".so", ".dll", ".def", ".dll.def",
                ".a", ".titan.h", ".ffi.h" }) do
            os.remove(name .. suffix)
        end
        os.execute("rm -rf " .. name .. ".so.dSYM")
    end
    if relocated then
        for _, name in ipairs({ "foreign_export_provider", "foreign_export_consumer" }) do
            os.remove(relocated .. "/" .. name .. (platform.windows and ".dll" or ".so"))
        end
        os.remove(relocated .. "/run.lua")
        assert(lfs.rmdir(relocated))
        relocated = nil
    end
end

describe("source-defined foreign functions", function()
    after_each(cleanup)

    it("resolves public foreign entries from a compiled shared provider", function()
        local ok, err = h.build_so_chain({
            { name = "foreign_export_provider", src = [[
                foreign function add(left: int, right: int): int
                    return left + right
                end
                foreign function address(): function(int, int): int
                    return add
                end
                local foreign function hidden(): int return 99 end
                function ordinary(): integer return 5 end
            ]] },
            { name = "foreign_export_consumer", src = [[
                local provider = import "foreign_export_provider"
                local foreign function inline_call(value: int): int
                    return provider.add { right = value, left = 2 }
                end
                foreign function raw_address(): function(int, int): int
                    return provider.add
                end
                foreign function raw_call(value: int): int
                    local callback: foreign function(int, int): int = provider.add
                    return callback(value, inline_call(2))
                end
                function exercise(): integer
                    local callback: foreign function(int, int): int = provider.add
                    if callback ~= raw_address() then return -1 end
                    if callback ~= provider.address() then return -2 end
                    return raw_call(33) + provider.ordinary()
                end
            ]] },
        })
        assert.truthy(ok, err)
        local csrc = read_file("foreign_export_consumer.c")
        local symbol = coder_names._foreign_func_name("foreign_export_provider", "add")
        assert.truthy(csrc:find("__atomic_compare_exchange_n", 1, true))
        assert.truthy(csrc:find("__atomic_load_n", 1, true))
        assert.falsy(csrc:find("extern int " .. symbol, 1, true))
        assert.falsy(csrc:find("->" .. symbol, 1, true))
        local header = read_file("foreign_export_provider.titan.h")
        assert.truthy(header:find("extern int " .. symbol, 1, true))
        assert.falsy(header:find("static inline int " .. symbol, 1, true))
        ok, err = h.call("foreign_export_consumer",
            [[
            assert(foreign_export_consumer.exercise() == 42)
            local provider = require "foreign_export_provider"
            assert(not pcall(function() return provider.add end))
            assert(not pcall(function() return provider.hidden end))
        ]])
        assert.truthy(ok, err)

        -- The build-time providers are absent. Both the consumer opener and
        -- its raw dependency must be found at the new runtime location.
        relocated = temporary.name()
        assert(os.remove(relocated))
        assert(lfs.mkdir(relocated))
        local suffix = platform.windows and ".dll" or ".so"
        for _, name in ipairs({ "foreign_export_provider", "foreign_export_consumer" }) do
            -- The temporary directory may be on another filesystem.
            assert(compiler_io.new_sync():write_file(
                relocated .. "/" .. name .. suffix, read_file(name .. suffix)))
            assert(os.remove(name .. suffix))
            assert(os.remove(name .. ".titan.h"))
            assert(os.remove(name .. ".ffi.h"))
        end
        local script = assert(io.open(relocated .. "/run.lua", "wb"))
        assert(script:write(string.format(
            "package.cpath=%q .. ';' .. package.cpath\n",
            relocated .. "/?" .. suffix)))
        assert(script:write([[assert(require("foreign_export_consumer").exercise() == 42)]]))
        assert(script:close())
        local prefix = require("spec.support.installed_prefix").active()
        local arguments = {
            platform.windows and "env.exe" or "env",
            "MSYS2_ENV_CONV_EXCL=TITAN_PATH_0_6",
            "TITAN_PATH_0_6=" .. relocated .. ";" .. prefix .. "/lib/titan/0.6",
            "TITAN_PATH=",
            prefix .. "/bin/lua" .. (platform.windows and ".exe" or ""),
            relocated .. "/run.lua",
        }
        local result = compiler_io.new_sync():run(arguments, { stderr_to_stdout = true })
        assert.truthy(result.started and result.ok, result.output or result.diagnostic)
    end)

    it("uses the declaring owner binding in copied local foreign inline bodies", function()
        local ok, err = h.build_so_chain({
            { name = "foreign_slot_provider", src = [[
                foreign function add(left: int, right: int): int
                    return left + right
                end
                foreign function address(): function(int, int): int
                    return add
                end
            ]] },
        })
        assert.truthy(ok, err)
        local sources = {
            foreign_slot_owner = [[
                local provider = import "foreign_slot_provider"
                local foreign function copied(value: int): int
                    return provider.add(value, 2)
                end
                local foreign function imported_address(): function(int, int): int
                    return provider.add
                end
            ]],
            foreign_slot_consumer = [[
                local owner = import "foreign_slot_owner.titan"
                local provider = import "foreign_slot_provider"
                function exercise(): integer
                    if owner.imported_address() ~= provider.address() then return -1 end
                    return owner.copied(40)
                end
            ]],
        }
        for name, source in pairs(sources) do
            assert.is_nil(lfs.attributes(name .. ".titan"))
            local file = assert(io.open(name .. ".titan", "wb"))
            assert(file:write(source))
            assert(file:close())
        end
        -- A fresh compiler owns all metadata mappings, allowing Windows to
        -- retire the fixture DLLs after this child exits.
        ok, err = h.call("lfs", string.format("package.path=%q\npackage.cpath=%q\n",
            package.path, package.cpath) .. [[
            local h = require "spec.support.helpers"
            local driver = require "titan-compiler.driver"
            local checker = require "titan-compiler.checker"
            h.reset(true)
            local deps = {}
            local loader = driver.defaultloader(deps)
            driver.with_loader(loader, function(loader)
                local typ, errors = checker.checkimport("foreign_slot_consumer", loader)
                assert(typ, errors)
                assert(#errors == 0, table.concat(errors, "\n"))
                assert(not deps.foreign_slot_provider)
                local names = { "foreign_slot_owner", "foreign_slot_consumer" }
                assert(driver.prepare_foreign_headers(names, driver.imported, false))
                local objects = {}
                for _, name in ipairs(names) do
                    local ok, err = driver.compile_module(name, driver.imported[name], deps, false)
                    assert(ok, err)
                    objects[#objects + 1] = name .. ".o"
                end
                assert(driver.compile_library("foreign_slot_consumer", objects, nil, false))
            end)
            assert(require("foreign_slot_consumer").exercise() == 42)
        ]])
        assert.truthy(ok, err)
        local header = read_file("foreign_slot_owner.titan.h")
        assert.truthy(header:find("extern TITAN_SOURCE_LOCAL int (*", 1, true))
        assert.truthy(header:find("foreign_slot_owner_", 1, true))
        assert.truthy(header:find("__atomic_load_n", 1, true))
        assert.truthy(header:find("static inline int ", 1, true))
    end)

    it("calls imported declarations without expanding same-name function macros", function()
        h.with_extra_cflags({"-O3", "-Wall", "-Werror"}, function()
            with_header([[
                int ffi_declared_value = 41;
                int ffi_shadow_value = 99;
                static inline int *ffi_declared_pointer(void) {
                    return &ffi_declared_value;
                }
                static inline int ffi_declared_add(int value) { return value + 2; }
                #define ffi_declared_pointer() ((const int *)&ffi_shadow_value)
                #define ffi_declared_add(value) ((value) + 100)
                #define ffi_declared_alias ffi_declared_add
            ]], function(header)
                h.run_coder([[
                    foreign import "]] .. header .. [["

                    function ordinary(): integer
                        return ffi.ffi_declared_pointer()[0]
                    end
                    foreign function raw(): int
                        return ffi.ffi_declared_pointer()[0]
                    end
                    function source_body(): integer
                        return raw()
                    end
                    function direct(): integer
                        return ffi.ffi_declared_add(7)
                    end
                    function alias(): integer
                        return ffi.ffi_declared_alias(7)
                    end
                    function indirect(): integer
                        local callback: foreign function(int): int = ffi.ffi_declared_add
                        return callback(7)
                    end
                ]], [[
                    assert(test.ordinary() == 41)
                    assert(test.source_body() == 41)
                    assert(test.direct() == 9 and test.indirect() == 9)
                    assert(test.alias() == 9)
                ]])
            end)
        end)
    end)

    it("preserves the string.h prototype under const-generic feature macros", function()
        h.with_extra_cflags({"-D_GNU_SOURCE", "-O3", "-Wall", "-Werror"}, function()
            h.run_coder([[
                foreign import "string.h"
                function contains_nul(text: string): boolean
                    return ffi.memchr(text, 0, #text) ~= nil
                end
            ]], [[
                assert(not test.contains_nul("ordinary"))
                assert(not test.contains_nul(""))
                assert(test.contains_nul("before\0after"))
            ]])
        end)
    end)

    it("emits both reserved module headers and the UCN entry family", function()
        with_header([[
            #ifdef TITAN_TEST_FOREIGN_HEADER_SEEN
            #error foreign header included twice in one translation unit
            #endif
            #define TITAN_TEST_FOREIGN_HEADER_SEEN 1
            typedef int ffi_int;
            typedef int (*ffi_callback)(int);
            static int ffi_apply(ffi_callback callback, int value) {
                return callback(value);
            }
        ]], function(header)
            local csrc = h.compile_and_read_c([[
                foreign import "]] .. header .. [["

                local foreign function add_one(input: ffi_int): ffi_int
                    return input + 1
                end

                local foreign function choose(input: ffi_int): ffi_int
                    if input then return input else return 7 end
                end

                local foreign function choose_or(input: ffi_int): ffi_int
                    if input then return input end
                    return 8
                end

                local foreign function accumulate(limit: ffi_int): ffi_int
                    local total = 0
                    if limit then total = ffi.ffi_apply(add_one, total) end
                    for index = 1 as foreign ffi_int, limit do
                        total = total + index
                    end
                    return total + choose(0) + choose_or(0)
                end

                local function hidden(input: integer): integer
                    do
                        if input < 0 then raise "negative" end
                    catch
                        return 0
                    end
                    return input + 2
                end

                function exercise(input: integer): integer
                    return (ffi.ffi_apply(add_one, input as foreign ffi_int)
                        as integer) + hidden(accumulate(3) as integer)
                end
            ]])

            local generated = read_file("test.titan.h")
            assert.equal(GENERATED_HEADER_BANNER,
                generated:sub(1, #GENERATED_HEADER_BANNER))
            local add = coder_names._foreign_func_name("test", "add_one")
            local accumulate = coder_names._foreign_func_name("test", "accumulate")
            assert.truthy(add:find("\\u2133", 1, true))
            assert.truthy(generated:find("static inline ffi_int " .. add, 1, true))
            assert.truthy(generated:find("TITAN_SOURCE_LOCAL ffi_int " .. accumulate,
                1, true))
            assert.truthy(csrc:find('/test.titan.h"', 1, true))
            local ffi_include = assert(csrc:find('/test.ffi.h"', 1, true))
            local titan_include = assert(csrc:find('/test.titan.h"', 1, true))
            assert.is_true(ffi_include < titan_include)
            local ffi_contents = read_file("test.ffi.h")
            assert.truthy(ffi_contents:find(header, 1, true))
            assert.truthy(generated:find('/test.ffi.h"', 1, true))
            assert.falsy(generated:find(header, 1, true))
            assert.truthy(csrc:find("test_\\u2133_hidden_titan", 1, true))
            assert.falsy(csrc:find("titan_source_", 1, true))

            local pipe = assert(io.popen("nm test.o", "r"))
            local symbols = assert(pipe:read("*a"))
            assert.truthy(pipe:close())
            assert.truthy(symbols:find(
                coder_names._linkage_symbol_name(accumulate), 1, true), symbols)
            assert.falsy(symbols:find("\\u2133", 1, true), symbols)

            local ok, err = h.call("test", [[
                assert(test.exercise(4) == 29)
            ]])
            assert.truthy(ok, err)
        end)
    end)

    it("uses raw C scalar conditions, pointer truth, and evaluate-once calls",
    function()
        with_header([[
            typedef int ffi_int;
            static int ffi_counter = 0;
            static int ffi_next(void) { ffi_counter += 1; return ffi_counter; }
            static int ffi_counter_value(void) { return ffi_counter; }
            static int ffi_trace = 0;
            static int ffi_slots[2] = { 0, 0 };
            static void ffi_reset_trace(void) {
                ffi_trace = 0; ffi_slots[0] = 0; ffi_slots[1] = 0;
            }
            static int ffi_value(int digit, int value) {
                ffi_trace = ffi_trace * 10 + digit; return value;
            }
            static int *ffi_target(int digit, int index) {
                ffi_trace = ffi_trace * 10 + digit; return &ffi_slots[index];
            }
            static int ffi_trace_value(void) { return ffi_trace; }
            static int ffi_slot(int index) { return ffi_slots[index]; }
            typedef struct ffi_lvalue_holder {
                int *pointer;
                int index;
            } ffi_lvalue_holder;
            static ffi_lvalue_holder ffi_first_slot(void) {
                ffi_lvalue_holder holder;
                ffi_slots[0] = 0; ffi_slots[1] = 0;
                holder.pointer = &ffi_slots[0]; holder.index = 0;
                return holder;
            }
            static int ffi_retarget(ffi_lvalue_holder *holder) {
                holder->pointer = &ffi_slots[1]; return 9;
            }
            static int ffi_reindex(ffi_lvalue_holder *holder) {
                holder->index = 1; return 7;
            }
            typedef int (*ffi_callback)(int, int);
            typedef int (*ffi_unary_callback)(int);
            typedef void *ffi_void_pointer;
            static int ffi_old_callback(int value) { return 100 + value; }
            static int ffi_new_callback(int value) { return 200 + value; }
            static ffi_unary_callback ffi_get_callback(void) {
                return ffi_old_callback;
            }
            typedef struct ffi_callback_holder {
                ffi_unary_callback callback;
            } ffi_callback_holder;
            static ffi_callback_holder ffi_callback_holder_new(void) {
                ffi_callback_holder holder;
                holder.callback = ffi_old_callback;
                return holder;
            }
            static int ffi_retarget_callback(ffi_callback_holder *holder) {
                holder->callback = ffi_new_callback;
                return 7;
            }
            static int ffi_literals(_Bool flag, double number,
                                    const char *text) {
                return flag && number == 2.5 && text[0] == 'x';
            }
            static ffi_lvalue_holder *ffi_holder(void) {
                static ffi_lvalue_holder holder;
                holder.pointer = ffi_slots; holder.index = 1;
                return &holder;
            }
        ]], function(header)
            h.run_coder([[
                foreign import "]] .. header .. [["

                foreign function raw(limit: ffi_int): ffi_int
                    local total = 0
                    local pointer: foreign *ffi_int = nil
                    if pointer then total = 100 end
                    if limit then total = total + ffi.ffi_next() end
                    while total < limit do total = total + 1 end
                    repeat total = total - 1 until total == limit - 1
                    return total
                end

                foreign function sequence(): ffi_int
                    ffi.ffi_reset_trace()
                    local first, second =
                        ffi.ffi_value(1, 3), ffi.ffi_value(2, 4)
                    ffi.ffi_target(3, 0)[0], ffi.ffi_target(4, 1)[0] =
                        ffi.ffi_value(5, first), ffi.ffi_value(6, second)
                    return ffi.ffi_trace_value()
                        + ffi.ffi_slot(0) + ffi.ffi_slot(1)
                end

                foreign function prepared_pointer_target(): ffi_int
                    local holder = ffi.ffi_first_slot()
                    holder.pointer[0] = ffi.ffi_retarget(holder)
                    return ffi.ffi_slot(0) * 10 + ffi.ffi_slot(1)
                end

                foreign function prepared_index_target(): ffi_int
                    local holder = ffi.ffi_first_slot()
                    holder.pointer[holder.index] = ffi.ffi_reindex(holder)
                    return ffi.ffi_slot(0) * 10 + ffi.ffi_slot(1)
                end

                foreign function prepared_indirect_callee(): ffi_int
                    local holder = ffi.ffi_callback_holder_new()
                    return holder.callback(ffi.ffi_retarget_callback(holder))
                end

                foreign function roundtrip_pointer(
                    pointer: ffi_void_pointer
                ): ffi_int
                    local callback = pointer as foreign ffi_unary_callback
                    return callback(1)
                end

                foreign function named(
                    left: ffi_int,
                    right: ffi_int
                ): ffi_int
                    return left * 10 + right
                end

                foreign function raw_forms(callback: ffi_callback): ffi_int
                    local negative: foreign ffi_int = -1
                    local computed = callback(2, 5)
                    local selected: foreign ffi_callback = named
                    local selected_value = selected(1, 2)
                    local holder = ffi.ffi_holder()
                    holder.pointer[holder.index] = 6
                    return named { right = computed, left = negative }
                        + ffi.ffi_literals(true, 2.5, "x")
                        + holder.pointer[holder.index] + selected_value
                end

                function exercise(): integer
                    return (raw(4) as integer) * 10
                        + (ffi.ffi_counter_value() as integer)
                end

                function sequencing(): integer
                    return sequence() as integer
                end

                function prepared_targets(): integer
                    return (prepared_pointer_target() as integer) * 10
                        + (prepared_index_target() as integer)
                end

                function forms(): integer
                    return raw_forms(named) as integer
                end

                function indirect_callee(): integer
                    return prepared_indirect_callee() as integer
                end

                function roundtrip(): integer
                    local pointer =
                        ffi.ffi_get_callback() as foreign ffi_void_pointer
                    return roundtrip_pointer(pointer) as integer
                end
            ]], [[
                assert(test.exercise() == 31)
                assert(test.sequencing() == 123463)
                assert(test.prepared_targets() == 970)
                assert(test.forms() == 34)
                assert(test.indirect_callee() == 107)
                assert(test.roundtrip() == 101)
            ]])
        end)
    end)

    it("runs foreign floating numeric loops in both directions", function()
        with_header([[
            typedef double ffi_double;
        ]], function(header)
            h.run_coder([[
                foreign import "]] .. header .. [["

                foreign function float_loops(): ffi_double
                    local total: foreign ffi_double = 0.0
                    for up = 0.0, 1.0, 0.25 do
                        total = total + up
                    end
                    for down = 1.0, 0.0, -0.25 do
                        total = total + down
                    end
                    return total
                end

                function result(): float
                    return float_loops() as float
                end
            ]], [[
                assert(test.result() == 5.0)
            ]])
        end)
    end)

    it("writes local pointer outputs and uses native size and alignment", function()
        with_header([[
            #include <stddef.h>
            typedef struct ffi_item { int value; } ffi_item;
            static int ffi_outputs(ffi_item **item, const char **text) {
                static ffi_item object = { 7 };
                *item = &object;
                *text = "x";
                return 0;
            }
            static int ffi_layout(size_t size, size_t alignment) {
                return size == sizeof(ffi_item)
                    && alignment == _Alignof(ffi_item);
            }
        ]], function(header)
            h.run_coder([[
                foreign import "]] .. header .. [["

                foreign function outputs(): int
                    local item: foreign *ffi_item = nil
                    local text: foreign const *char = nil
                    ffi.ffi_outputs(item, text)
                    local erased: foreign *void = item
                    if erased ~= item then return -1 end
                    if ffi.ffi_layout(foreign ffi_item.sizeof,
                                    foreign ffi_item.alignof) == 0 then return -2 end
                    return item.value + (text[0] as foreign int)
                end

                function result(): integer
                    return outputs()
                end

                function ordinary_result(): integer
                    local item: foreign *ffi_item = nil
                    local text: foreign const *char = nil
                    ffi.ffi_outputs(item, text)
                    return item.value + (text[0] as integer)
                end
            ]], [[
                assert(test.result() == 127)
                assert(test.ordinary_result() == 127)
            ]])
        end)
    end)

    it("evaluates foreign elseif conditions lazily and once", function()
        with_header([[
            static int ffi_trace = 0;
            static int ffi_condition(int digit, int selected) {
                ffi_trace = ffi_trace * 10 + digit;
                return digit == selected;
            }
            static void ffi_clear(void) { ffi_trace = 0; }
            static int ffi_observed(void) { return ffi_trace; }
        ]], function(header)
            h.run_coder([[
                foreign import "]] .. header .. [["

                foreign function select_arm(selected: int): int
                    ffi.ffi_clear()
                    local result: foreign int = 0
                    if ffi.ffi_condition(1, selected) then
                        result = 10
                    elseif ffi.ffi_condition(2, selected) then
                        result = 20
                    elseif ffi.ffi_condition(3, selected) then
                        result = 30
                    else
                        result = 40
                    end
                    return ffi.ffi_observed() * 100 + result
                end

                function result(selected: integer): integer
                    return select_arm(selected)
                end
            ]], [[
                assert(test.result(1) == 110)
                assert(test.result(2) == 1220)
                assert(test.result(3) == 12330)
                assert(test.result(4) == 12340)
            ]])
        end)
    end)

    it("uses the C ABI for source foreign call statements and deferred calls",
    function()
        with_header([[
            static int ffi_value = 0;
            static void ffi_reset(void) { ffi_value = 0; }
            static int ffi_add(int value) { ffi_value += value; return ffi_value; }
            static int ffi_current(void) { return ffi_value; }
        ]], function(header)
            h.run_coder([[
                foreign import "]] .. header .. [["

                foreign function add(amount: int)
                    ffi.ffi_add(amount)
                end

                foreign function add_result(amount: int): int
                    return ffi.ffi_add(amount)
                end

                function exercise(): integer
                    ffi.ffi_reset()
                    defer add(20)
                    add(1)
                    add_result(2)
                    return ffi.ffi_current()
                end

                function current(): integer
                    return ffi.ffi_current()
                end
            ]], [[
                assert(test.exercise() == 3)
                assert(test.current() == 23)
            ]])
        end)
    end)

    it("preserves raw pointer carriers in written pointer casts", function()
        with_header([[
            static void *ffi_slot = 0;
            static void *ffi_pointer_source(void) { return &ffi_slot; }
            static void ffi_pointer_sink(void **pointer) {
                *pointer = (void *)"written";
            }
            static int ffi_written(void) {
                return ffi_slot != 0 && ((const char *)ffi_slot)[0] == 'w';
            }
        ]], function(header)
            h.run_coder([[
                foreign import "]] .. header .. [["
                foreign type Pointer = *void

                foreign function call_pointer(): *Pointer
                    return ffi.ffi_pointer_source() as foreign *Pointer
                end

                foreign function local_pointer(): int
                    local raw = ffi.ffi_pointer_source()
                    ffi.ffi_pointer_sink(raw as foreign *Pointer)
                    if raw ~= ffi.ffi_pointer_source() then return -1 end
                    return ffi.ffi_written()
                end

                function result(): integer
                    if call_pointer() ~= ffi.ffi_pointer_source() then return -2 end
                    return local_pointer()
                end
            ]], [[
                assert(test.result() == 1)
            ]])
        end)
    end)

    it("renders the closed raw-C variable and inline-shape branches", function()
        local cmodule = types.CModule("fixture", {}, {})
        local ctx = coder_declarations._new_foreign_context({ module = "test" })
        local _, cname = coder_declarations._foreign_raw_var(ctx, {
            _tag = "Ast.VarDot",
            name = "C_VALUE",
            exp = { _type = cmodule },
            _type = types.CInteger("int", true, 3, 32),
        })
        assert.equal("C_VALUE", cname)

        local cint = types.CInteger("int", true, 3, 32)
        local size = { _tag = "Type.CPseudoSize", name = "sizeof", ctype = cint }
        local _, sizeof = coder_declarations._foreign_raw_var(ctx, {
            _tag = "Ast.VarDot",
            name = "sizeof",
            exp = { _type = cint },
            _decl = size,
            _type = cint,
        })
        assert.truthy(sizeof:find("sizeof", 1, true))

        local foreign = types.ModuleMember("other", "callback",
            types.CFunction({}, cint, false, nil), {})
        foreign._foreign_source = true
        foreign.islocal = true
        local _, reference = coder_declarations._foreign_raw_var(ctx, {
            _tag = "Ast.VarDot",
            name = "callback",
            exp = { _type = { _tag = "Type.Module" } },
            _decl = foreign,
            _type = foreign.type,
        })
        assert.equal(coder_names._foreign_func_name("other", "callback"), reference)

        assert.has_error(function()
            coder_declarations._foreign_raw_var(ctx, {
                _tag = "Ast.VarName", name = "missing",
            })
        end, "foreign variable lacks a C name: missing")
        assert.has_error(function()
            coder_declarations._foreign_raw_var(ctx, { _tag = "Ast.VarInvalid" })
        end, "unsupported foreign variable Ast.VarInvalid")

        local ret = { _tag = "Ast.StatReturn" }
        local block = function(stats)
            return { _tag = "Ast.StatBlock", stats = stats }
        end
        assert.is_true(coder_declarations._foreign_function_is_inline({
            islocal = true,
            block = block({ {
                _tag = "Ast.StatIf",
                thens = { { block = block({ ret }) } },
                elsestat = block({ ret }),
            } }),
        }))
        assert.is_true(coder_declarations._foreign_function_is_inline({
            islocal = true,
            block = block({ {
                _tag = "Ast.StatIf",
                thens = { { block = block({ ret }) } },
                elsestat = false,
            }, ret }),
        }))
    end)

    it("uses linkage spelling for native trace-name registry keys", function()
        local csrc = h.compile_and_read_c([[
            function visible(): integer
                return 1
            end
        ]])
        assert.truthy(csrc:find(
            'lua_setfield(L, -2, "test_\\342\\204\\263_visible_titan");',
            1, true))
        assert.falsy(csrc:find(
            'lua_setfield(L, -2, "test_\\\\u2133_visible_titan");',
            1, true))
    end)
end)
